<script setup>
import WbProductOperationDialog from '../../components/listing/WbProductOperationDialog.vue';
import WbPublishMediaSummary from '../../components/listing/WbPublishMediaSummary.vue';
import{ref,onMounted,onBeforeUnmount}from'vue';import{useRouter}from'vue-router';import{ElMessage,ElMessageBox}from'element-plus';import{apiClient,currentApiCacheScope}from'../../utils/api.js';import{wbPublishStatus,wbPublishPhase}from'../../../../src/shared/wb-publish-status.js';import{shanghaiDateTimeText}from'../../utils/shanghai-date.js';
const router=useRouter(),rows=ref([]),loading=ref(false),selected=ref(null),operation=ref(null);let timer,generation=0;
const sourceId=job=>Number(job.payload.source_publish_job_id||job.id);
function edit(job){router.push({path:'/listing-automation',query:{platform:'wb',wbDraftId:String(job.draft_id),wbRecordId:String(sourceId(job))}});}
function operate(job,action){operation.value={sourceJobId:sourceId(job),draftId:Number(job.draft_id),action};}
function label(job){if(job.status==='completed'&&job.payload.operation_action==='archive')return '已归档';return wbPublishStatus(job.status);}
async function load(){const id=++generation,scope=currentApiCacheScope();loading.value=true;try{const[created,operations]=await Promise.all([apiClient.get('/api/wb/publish-jobs',{noCache:true}),apiClient.get('/api/wb/product-operations',{noCache:true})]);if(id!==generation||scope!==currentApiCacheScope())return;rows.value=[...created.rows.map(j=>({...j,kind:'publish',key:'publish:'+j.id})),...operations.rows.map(j=>({...j,kind:'operation',key:'operation:'+j.id}))].sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at)));selected.value=selected.value?rows.value.find(row=>row.key===selected.value.key)||null:null;clearTimeout(timer);if(rows.value.some(row=>['queued','processing'].includes(row.status)))timer=setTimeout(load,10000);}catch(e){if(id===generation&&scope===currentApiCacheScope())ElMessage.error(e.message);}finally{if(id===generation)loading.value=false;}}
async function resume(job,retry=false,mediaConfirmed=false){try{await ElMessageBox.confirm(mediaConfirmed?'已核对以下 WB 返回的线上图片视频内容，继续设置本次确认的价格。':retry?'将重试当前未确认步骤，不会重复创建商品。':'将从本次提交资料继续核对平台结果。','继续平台操作',{type:'warning'});}catch{return;}const scope=currentApiCacheScope();try{await apiClient.post(job.kind==='operation'?'/api/wb/product-operation/resume':'/api/wb/listing-publish/resume',{job_id:job.id,retry,media_confirmed:mediaConfirmed});if(scope===currentApiCacheScope())await load();}catch(e){if(scope===currentApiCacheScope())ElMessage.error(e.message);}}
function reset(){generation++;clearTimeout(timer);rows.value=[];selected.value=null;operation.value=null;load();}
onMounted(()=>{load();window.addEventListener('erp:auth-scope-changed',reset);});onBeforeUnmount(()=>{generation++;clearTimeout(timer);window.removeEventListener('erp:auth-scope-changed',reset);});
</script>
<template><div class="wb-publish-records"><div class="records-header"><h3>WB 上架记录</h3><el-button :loading="loading" @click="load">刷新结果</el-button></div><el-table :data="rows" v-loading="loading" border stripe row-key="key" empty-text="暂无 WB 发布记录"><el-table-column label="记录号" width="120"><template #default="{row}">{{row.kind==='operation'?'操作':'上架'}} {{row.id}}</template></el-table-column><el-table-column prop="shop_name" label="店铺" width="180"/><el-table-column label="商品" min-width="280"><template #default="{row}"><p v-for="item in row.state.items" :key="item.vendor_code">{{item.vendor_code}}<small v-if="item.nm_id"> · WB {{item.nm_id}}</small></p></template></el-table-column><el-table-column label="状态" width="150"><template #default="{row}">{{label(row)}}</template></el-table-column><el-table-column prop="message" label="处理结果" min-width="300"/><el-table-column label="更新（北京）" width="180"><template #default="{row}">{{shanghaiDateTimeText(row.updated_at,{assumeUtcWhenNaive:true})}}</template></el-table-column><el-table-column label="操作" width="300" fixed="right"><template #default="{row}"><el-button link type="primary" @click="selected=row">详情</el-button><el-button link type="primary" @click="edit(row)">编辑</el-button><el-button link @click="operate(row,'archive')">归档</el-button><el-button link @click="operate(row,'republish')">恢复原商品</el-button><el-button v-if="['needs_review','paused'].includes(row.status)" link @click="resume(row)">继续核对</el-button></template></el-table-column></el-table>
<el-drawer v-if="selected" :model-value="true" title="WB 发布详情" size="min(900px,95vw)" @close="selected=null"><el-alert :title="label(selected)+'：'+selected.message" :closable="false"/><p>店铺：{{selected.shop_name}}</p><p>本次提交资料 · 草稿版本 {{selected.draft_revision}} · {{selected.payload.currency}}</p><section v-for="(item,index) in selected.state.items" :key="item.vendor_code"><h4>{{selected.payload.variants?.[index]?.card?.title||selected.payload.card?.title}}</h4><p>{{item.vendor_code}} · {{wbPublishPhase(item.phase)}} · {{item.nm_id?'WB '+item.nm_id:'等待商品编号'}}</p><WbPublishMediaSummary :row="selected.payload.variants?.[index]||selected.payload" :phase="item.phase"/><template v-if="item.actual_media"><h4>WB 返回的线上媒体，请核对内容</h4><WbPublishMediaSummary :row="item.actual_media"/></template><pre v-if="item.price_errors?.length">{{JSON.stringify(item.price_errors,null,2)}}</pre></section><div class="record-actions"><el-button @click="edit(selected)">编辑草稿</el-button><el-button @click="operate(selected,'archive')">归档到 WB 回收站</el-button><el-button type="primary" @click="operate(selected,'republish')">恢复原商品并重新上架</el-button><el-button v-if="['needs_review','paused'].includes(selected.status)" @click="resume(selected)">继续核对</el-button><el-button v-if="selected.kind==='operation'&&selected.status==='needs_review'&&selected.state.items.some(i=>i.phase==='media'&&i.actual_media)" type="primary" @click="resume(selected,false,true)">已核对线上媒体，继续价格步骤</el-button><el-button v-if="selected.status==='needs_review'&&(selected.state.grouping||(selected.kind==='operation'?['archive','recover','update','media','price']:['media','price']).includes(selected.state.items.find(item=>item.phase!=='done')?.phase))" type="warning" @click="resume(selected,true)">重试当前步骤</el-button></div></el-drawer>
<WbProductOperationDialog v-if="operation" v-bind="operation" @close="operation=null" @submitted="operation=null;load()"/></div></template>
<style scoped>.wb-publish-records{display:grid;gap:16px}.records-header{display:flex;justify-content:space-between;align-items:center}.records-header h3{margin:0}.wb-publish-records p{margin:5px 0}.wb-publish-records small{color:var(--el-text-color-secondary)}.record-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:16px}.record-actions .el-button{margin:0}</style>
